    end
    on_intel do
      url "https://blindpass.app/cli/0.2.50/blindpass-0.2.50-darwin-x64.tar.gz"
      sha256 "ec5ca52e84e092a132c38df36be1bb611e0679c87ea190b39881143e8e632db4"
    end
  end

  on_linux do
    on_arm do
