      sha256 "e25a71e2f93ea9e8715c6c8637429460bbdbf633e62e54f57dd2f937ba63f0be"
    end
    on_intel do
      url "https://blindpass.app/cli/0.2.50/blindpass-0.2.50-linux-x64.tar.gz"
